	@Test
	void repeatedBagDagStaysLinearPastLongMultiplicity() throws Exception {
		try (var memory = memory(); var factory = new PhysicalEventKey.Factory("source", memory)) {
			var node = factory.tryOrigin(PhysicalEventKey.LEAF, "leaf", null, null);
			for (int doubling = 0; doubling < Long.SIZE; doubling++) {
				node = factory.tryOrigin(PhysicalEventKey.JOIN, "join", node, node);
				assertNotNull(node);
			}
			PhysicalEventKey key = new PhysicalEventKey(node, "current");
			byte[] bytes = encode(key);
			try (var in = input(bytes)) {
				assertEquals(-1, in.readInt(), "the first shared string is a definition reference");
				assertEquals("current", LearningKeyCodec.readString(in, "current"));
				int reservedScratchCapacity = in.readInt();
				assertTrue(reservedScratchCapacity >= 65, "scratch extent is not the count of emitted DAG nodes");
				assertEquals(65, in.readInt(), "ordered duplicate edges must not expand BAG multiplicity");
				ArrayList<String> dictionary = new ArrayList<>();
				dictionary.add("current");
				for (int definition = 1; definition <= 65; definition++) {
					assertEquals(definition == 1 ? PhysicalEventKey.LEAF : PhysicalEventKey.JOIN, in.readByte());
					assertEquals("source", sharedString(in, dictionary));
					assertEquals(definition == 1 ? "leaf" : "join", sharedString(in, dictionary));
					assertEquals(definition - 1, in.readInt());
					assertEquals(definition == 1 ? 0 : definition - 1, in.readInt());
				}
				assertEquals(65, in.readInt(), "the root references the final canonical DAG definition");
				assertEquals(0, in.available());
			}
			assertEquals(key, PhysicalEventKey.readFrom(input(bytes), PhysicalEventKey.MAXIMUM_EVENTS));
			assertTrue(bytes.length < 4096, "the actual 65-node unit graph is bounded independently of 2^64");
		}
	}

	private static String sharedString(DataInputStream in, List<String> dictionary) throws IOException {
		int reference = in.readInt();
		if (reference < 0) {
			assertEquals(-(dictionary.size() + 1), reference, "definitions use exact next dictionary IDs");
			dictionary.add(LearningKeyCodec.readString(in, "shared definition"));
			return dictionary.get(dictionary.size() - 1);
		}
		assertTrue(reference > 0 && reference <= dictionary.size());
		return dictionary.get(reference - 1);
	}

