	@Test
	void legacyAndIndependentCellsShareTheSameCountCapAndLeases() {
		FrontierLearningModel model = new FrontierLearningModel(1);
		LogicalLearningKey logical = LogicalLearningKey.of("filter", "a", "b", "c", "x", "none", "bag", "default");
		var legacy = model.resolve(logical, PHYSICAL, APPLICABILITY, false, true, false);
		assertNotNull(legacy);
		assertNull(model.resolvePhysical(key("source", "one"), PHYSICAL, APPLICABILITY, false));
		model.release(legacy);
		var physical = model.resolvePhysical(key("source", "one"), PHYSICAL, APPLICABILITY, false);
		assertNotNull(physical);
		assertEquals(1, model.physicalInventory().cells());
		assertEquals(1, model.physicalInventory().independentCells());
		assertEquals(1, model.physicalInventory().leasedCells());
		assertNull(model.resolvePhysical(key("source", "two"), PHYSICAL, APPLICABILITY, false));
		long bytes = model.physicalInventory().modeledBytes();
		assertTrue(bytes > 48L);
		model.release(physical);
		var replacement = model.resolvePhysical(key("source", "two"), PHYSICAL, APPLICABILITY, false);
		assertNotNull(replacement);
		assertEquals(1, model.physicalInventory().cells());
		model.release(replacement);
		model.clear();
		assertEquals(0, model.physicalInventory().cells());
		assertEquals(0, model.physicalInventory().leasedCells());
		assertEquals(0, model.physicalInventory().independentCells());
		assertTrue(model.physicalInventory().modeledBytes() < bytes, "clear releases all key/DAG payloads");
		assertTrue(model.physicalInventory().modeledBytes() > 48L,
				"clear does not pretend that the backing table shrank");
	}

