	@Test
	void prefixWriteBytesGrowByTheNewDefinitionsInsteadOfEveryOldTail() throws Exception {
		int first = encodedPrefixes(32).length;
		int second = encodedPrefixes(64).length;
		int third = encodedPrefixes(96).length;
		assertEquals(second - first, third - second,
				"equal new prefix counts add the same fixed-width definitions/cells, with no repeated old tails");
	}

