	@Test
	void aGlobalReferenceRetainsItsExactGraphAndCannotClaimASmallerNodeBound() throws Exception {
		PhysicalEventKey key;
		try (var memory = memory(); var factory = new PhysicalEventKey.Factory("source", memory)) {
			var leaf = factory.tryOrigin(PhysicalEventKey.LEAF, "leaf", null, null);
			key = new PhysicalEventKey(factory.tryOrigin(PhysicalEventKey.APPEND, "append", leaf, null), "current");
		}
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (var context = new PhysicalEventKey.WriteContext()) {
			key.writeTo(new DataOutputStream(bytes), context);
			key.writeTo(new DataOutputStream(bytes), context);
		}
		DataInputStream input = input(bytes.toByteArray());
		try (var context = new PhysicalEventKey.ReadContext()) {
			assertEquals(key, PhysicalEventKey.readFrom(input, 8192, context));
			assertEquals(key, PhysicalEventKey.readFrom(input, 8192, context));
			assertEquals(0, input.available());
		}
		bytes.reset();
		key.writeTo(new DataOutputStream(bytes));
		DataOutputStream malformed = new DataOutputStream(bytes);
		malformed.writeInt(1); // Existing current-frame string.
		malformed.writeInt(1); // A two-node root cannot claim a one-node scratch extent.
		malformed.writeInt(0);
		malformed.writeInt(2); // Existing exact two-node root.
		input = input(bytes.toByteArray());
		DataInputStream invalidInput = input;
		try (var context = new PhysicalEventKey.ReadContext()) {
			assertEquals(key, PhysicalEventKey.readFrom(invalidInput, 8192, context));
			assertThrows(IOException.class, () -> PhysicalEventKey.readFrom(invalidInput, 8192, context));
		}
	}

	private static byte[] encodedPrefixes(int count) throws Exception {
		FrontierLearningModel model = new FrontierLearningModel();
		try (var memory = memory(); var factory = new PhysicalEventKey.Factory("one exact source", memory)) {
			PhysicalEventKey.Origin origin = factory.tryOrigin(PhysicalEventKey.LEAF, "leaf", null, null);
			for (int index = 0; index < count; index++) {
				var lease = model.resolvePhysical(new PhysicalEventKey(origin, "current frame"), PHYSICAL,
						APPLICABILITY, false);
				assertNotNull(lease);
				model.release(lease);
				if (index + 1 < count) {
					origin = factory.tryOrigin(PhysicalEventKey.APPEND, "append", origin, null);
					assertNotNull(origin);
				}
			}
		}
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		model.writeTo(new DataOutputStream(bytes), true);
		return bytes.toByteArray();
	}

