	private static PhysicalEventKey key(String source, String frame) {
		try (var memory = memory(); var factory = new PhysicalEventKey.Factory(source, memory)) {
			return new PhysicalEventKey(factory.tryOrigin(PhysicalEventKey.LEAF, frame, null, null), frame);
		}
	}

	private static PackedCostTestSupport.ProviderMemoryOwner memory() {
		return PackedCostTestSupport.providerMemory(new PackedPlannerLimits(Long.MAX_VALUE, Long.MAX_VALUE));
	}

	private static byte[] encode(PhysicalEventKey key) throws IOException {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		key.writeTo(new DataOutputStream(bytes));
		return bytes.toByteArray();
	}

	private static DataInputStream input(byte[] bytes) {
		return new DataInputStream(new ByteArrayInputStream(bytes));
	}

	private static byte[] malformedDag(int kind) throws IOException {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		DataOutputStream out = new DataOutputStream(bytes);
		out.writeInt(-1);
		LearningKeyCodec.writeString(out, "current");
		out.writeInt(kind == 0 ? 8193 : 8);
		out.writeInt(kind == 1 ? 1 : 2);
		if (kind == 0) {
			return bytes.toByteArray();
		}
		out.writeByte(PhysicalEventKey.LEAF);
		out.writeInt(-2);
		LearningKeyCodec.writeString(out, "source");
		out.writeInt(-3);
		LearningKeyCodec.writeString(out, "first");
		out.writeInt(kind == 1 ? 1 : 0); // First node cannot refer forward to itself.
		out.writeInt(0);
		if (kind != 1) {
			out.writeByte(PhysicalEventKey.LEAF);
			out.writeInt(2);
			if (kind == 2) {
				out.writeInt(-4);
				LearningKeyCodec.writeString(out, "unreachable");
			} else {
				out.writeInt(3);
			} // Repeating the exact earlier definition is not canonical.
			out.writeInt(0);
			out.writeInt(0);
		}
		out.writeInt(kind == 1 ? 1 : 2);
		return bytes.toByteArray();
	}

	private static LegacyFixture fixture() throws Exception {
		byte[] raw;
		String identity;
		try (var stream = LmdbPhysicalEventIdentityTest.class.getResourceAsStream(
				"physical-event-v24/join-estimator.rjes.operators")) {
			assertNotNull(stream);
			raw = stream.readAllBytes();
		}
		try (var stream = LmdbPhysicalEventIdentityTest.class.getResourceAsStream(
				"physical-event-v24/physical-control-identity.txt")) {
			assertNotNull(stream);
			identity = new String(stream.readAllBytes(), StandardCharsets.UTF_8);
		}
		DataInputStream in = input(raw);
		assertEquals(24, in.readInt());
		SketchSnapshotIdentity.readFrom(in);
		in.readLong();
		in.readLong();
		in.readLong();
		in.readInt();
		for (int section = 0; section < 5; section++) {
			assertEquals(0, in.readInt(), "this genuine native control has no legacy compatibility-surface entries");
		}
		int start = raw.length - in.available();
		FrontierLearningModel model = FrontierLearningModel.readFrom(in, true);
		int end = raw.length - in.available();
		List<String> fields = identity.lines().toList();
		return new LegacyFixture(raw, start, end, model, LogicalLearningKey.parse(fields.get(0)),
				PhysicalResidualKey.parse(fields.get(1)), LearningApplicability.parse(fields.get(2)));
	}

	private record LegacyFixture(byte[] raw, int modelStart, int modelEnd, FrontierLearningModel model,
			LogicalLearningKey logical, PhysicalResidualKey physical, LearningApplicability applicability) {
	}
